import { load, save } from './storage';

const KEY = 'threads_v1';

export const loadThreads = () => load(KEY, [
  { id: 1, title: 'Ring 0: kernel exploit discussion', posts: [{ id: 11, author: 'neo', body: 'Detalles sobre exploit...' }] },
  { id: 2, title: 'Terminal themes & prompts', posts: [{ id: 21, author: 'trinity', body: 'Como configurar powerlevel10k' }] },
]);

export const saveThreads = (threads) => save(KEY, threads);

export const createThread = (thread) => {
  const threads = loadThreads();
  const newThread = { id: Date.now(), title: thread.title || 'Sin título', posts: thread.posts || [] };
  const updated = [newThread, ...threads];
  saveThreads(updated);
  return newThread;
};

export const addPost = (threadId, post) => {
  const threads = loadThreads();
  const updated = threads.map(t => t.id === threadId ? { ...t, posts: [...t.posts, { id: Date.now(), ...post }] } : t);
  saveThreads(updated);
  return updated.find(t=>t.id===threadId);
};

export const updateThread = (threadId, updates) => {
  const threads = loadThreads();
  const updated = threads.map(t => t.id === threadId ? { ...t, ...updates } : t);
  saveThreads(updated);
  return updated.find(t=>t.id===threadId);
};

export const deleteThread = (threadId) => {
  const threads = loadThreads();
  const updated = threads.filter(t => t.id !== threadId);
  saveThreads(updated);
  return updated;
};
